import { logger, DDBProxy, PatreonHelper, postJson, Secrets } from "../../../lib/_module";
import { ensureAssetsPrefix } from "./NativeShared";
/**
 * Adventure image enhancements - higher-quality replacement images served by the
 * proxy. Mirrors the muncher's `getEnhancedData` (ddb-adventure-muncher/munch/data/enhance.js).
 *
 * Endpoint: POST {proxy}/proxy/adventure/enhancement
 * body { cobalt, bookId } -> { success, data: [{ img, bookCode, scene_img?, hiresImg, ... }] }.
 * Enhancements are optional: any failure degrades to an empty list.
 */
export async function fetchEnhancements(bookId) {
    const cobalt = Secrets.getCobalt();
    if (!cobalt)
        return [];
    try {
        const json = await postJson(`${DDBProxy.getProxy()}/proxy/adventure/enhancement`, {
            cobalt,
            betaKey: PatreonHelper.getPatreonKey(),
            bookId: Number(bookId),
        });
        if (!json.success) {
            logger.info(`No enhancement data for book ${bookId}: ${json.message ?? "unknown"}`);
            return [];
        }
        const data = json.data ?? [];
        logger.info(`NativeEnhancements: ${data.length} enhancement entries for book ${bookId}`);
        return data;
    }
    catch (error) {
        logger.warn(`NativeEnhancements: fetch failed (${error.message}); continuing without enhancements`);
        return [];
    }
}
/** Map `assets/<path>` -> enhanced `hiresImg` url for every entry that has one.
 *
 * Per-entry keys: `img` (original path, used in journal HTML) and `scene_img`
 * (scene-only override, often points at a player-version map distinct from
 * the DM-version img). Both share the same hiresImg URL. Indexing both ensures
 * NativeAssetHandler's "enhancement-only" phase uploads scene backgrounds that
 * aren't in files.txt, so NativeSceneBuilder can resolve them via the assetMap.
 */
export function buildEnhancedUrlMap(list) {
    const map = new Map();
    for (const entry of list) {
        if (!entry?.hiresImg)
            continue;
        if (entry.img)
            map.set(ensureAssetsPrefix(entry.img), entry.hiresImg);
        if (entry.scene_img && entry.scene_img !== entry.img) {
            map.set(ensureAssetsPrefix(entry.scene_img), entry.hiresImg);
        }
    }
    return map;
}
/** Map `assets/<path>` -> enhancement display name (`adjustName` else `name`) for
 * every entry that carries one. Keyed by both `img` and `scene_img` so a scene
 * background resolved from either points at the same name. Lets NativeSceneBuilder
 * prefer the enrichment name over the parsed HTML caption (the proxy meta-data
 * name still overrides this post-create). Entries with no usable name are skipped.
 */
export function buildEnhancedNameMap(list) {
    const map = new Map();
    for (const entry of list) {
        const name = (typeof entry?.adjustName === "string" && entry.adjustName.trim() !== "")
            ? entry.adjustName.trim()
            : (typeof entry?.name === "string" && entry.name.trim() !== "" ? entry.name.trim() : null);
        if (!name)
            continue;
        if (entry.img)
            map.set(ensureAssetsPrefix(entry.img), name);
        if (entry.scene_img && entry.scene_img !== entry.img) {
            map.set(ensureAssetsPrefix(entry.scene_img), name);
        }
    }
    return map;
}
