import { logger } from "../../lib/_module";
/**
 * Create the applied copy of an enchantment profile on an item at import time, shaped the way
 * dnd5e 6.0's `EnchantActivity#applyEnchantment` shapes a runtime application. The copy must be
 * `transfer: true`: since dnd5e #7319 `EnchantmentData#isApplied` is `transfer && item`, so a
 * clone that keeps the profile's `transfer: false` is inert on the item (never yielded by
 * `Item5e#allApplicableEffects`, untracked by the enchantment registry, never expired). The
 * activity's duration is inherited the way the chat tray does it and change formulas are
 * resolved against the origin, while the rider collection still keys off the create options.
 */
export async function linkSelectedEnchantment(item, effect, activity, featureName) {
    const effectData = effect.toObject();
    const profileId = effectData._id;
    effectData.origin = activity.uuid;
    effectData.transfer = true;
    effectData.disabled = false;
    foundry.utils.setProperty(effectData, "flags.dae.transfer", true);
    foundry.utils.setProperty(effectData, "flags.dnd5e.enchantmentProfile", profileId);
    foundry.utils.setProperty(effectData, "system.origin.activity", activity.uuid);
    foundry.utils.setProperty(effectData, "system.origin.profile", profileId);
    const inherited = activity.getAppliedEffectChanges?.(effect, { target: item }) ?? {};
    if (!foundry.utils.isEmpty(inherited))
        foundry.utils.mergeObject(effectData, inherited);
    const forApplication = ActiveEffect.implementation.forApplication;
    if (forApplication && effectData.system?.changes) {
        effectData.system.changes = await forApplication(effectData.system.changes, activity, item);
    }
    const createOperation = {
        parent: item,
        keepOrigin: true,
        dnd5e: {
            enchantmentProfile: profileId,
            activityId: activity._id,
        },
    };
    const applied = await ActiveEffect.create(effectData, createOperation);
    logger.debug(`Applied enchantment effect from ${featureName} to ${item.name}`, {
        effect: effectData,
        applied,
    });
}
/**
 * Does every `targetItemMatches` clause hold for the item? An array-valued field (the weapon's
 * scraped `classFeatures`, used to find the DDB-marked pact weapon) matches when it contains the
 * value; anything else must equal it.
 */
export function matchFields(item, flags) {
    for (const flag of flags) {
        const itemValue = foundry.utils.getProperty(item, flag.field);
        if (itemValue === undefined)
            return false;
        if (Array.isArray(itemValue)) {
            if (!itemValue.includes(flag.value))
                return false;
        }
        else if (itemValue !== flag.value) {
            return false;
        }
    }
    return true;
}
export async function linkSelectedEnchantments(actor) {
    const items = actor.getEmbeddedCollection("Item");
    for (const item of items) {
        const enchantmentFlag = foundry.utils.getProperty(item, "flags.ddbimporter.transferEnchantment");
        if (!enchantmentFlag)
            continue;
        logger.debug(`Found enchantment transfer flag on item ${item.name}`, {
            item,
            enchantmentFlag,
        });
        const effect = item.getEmbeddedCollection("ActiveEffect")
            .find((e) => e._id === enchantmentFlag.effectId);
        if (!effect)
            continue;
        // loot items don't have activities, so we can't link the enchantment to them
        if (!item.system.activities)
            continue;
        // dnd5e-types types the initialized ActivitiesField as a plain record; the runtime value is an ActivityCollection
        const enchantActivities = item.system.activities
            .getByType("enchant");
        const activity = enchantActivities.find((a) => a._id === enchantmentFlag.activityId);
        if (!activity)
            continue;
        let targetItem = null;
        if ("equipped" in item.system && item.system.equipped === false)
            continue;
        if ("attuned" in item.system && item.system.attuned === false) {
            if (item.system.attunement === "required")
                continue;
        }
        if (enchantmentFlag.targetItemId === "self") {
            targetItem = item;
        }
        else if (enchantmentFlag.targetItemName) {
            targetItem = items.find((i) => (foundry.utils.getProperty(i, "flags.ddbimporter.originalName") ?? i.name) === enchantmentFlag.targetItemName) ?? null;
        }
        else if (enchantmentFlag.targetItemMatches) {
            const matchedFields = enchantmentFlag.targetItemMatches;
            const targetItems = items.filter((i) => matchFields(i, matchedFields));
            if (targetItems.length === 0) {
                logger.warn(`No items matched for enchantment transfer on ${item.name}. Skipping enchantment transfer.`, {
                    item,
                    enchantmentFlag,
                    items,
                });
            }
            else {
                for (const matchedItem of targetItems) {
                    await linkSelectedEnchantment(matchedItem, effect, activity, item.name);
                }
                continue;
            }
        }
        if (!targetItem)
            continue;
        await linkSelectedEnchantment(targetItem, effect, activity, item.name);
    }
}
export async function createInfusedItems(ddb, actor) {
    if (!ddb.infusions?.item || !ddb.infusions?.infusions?.definitionData)
        return;
    const rollData = actor.getRollData();
    for (const i of actor.getEmbeddedCollection("Item")) {
        const item = i;
        const infusedItem = ddb.infusions.item.find((mapping) => mapping.itemId === item.flags?.ddbimporter?.definitionId
            && mapping.inventoryMappingId === item.flags?.ddbimporter?.id
            && mapping.itemTypeId === item.flags?.ddbimporter?.definitionEntityTypeId);
        if (!infusedItem)
            continue;
        // add infused item effect
        const infusionFeature = actor.getEmbeddedCollection("Item").find((i) => foundry.utils.getProperty(i, "flags.ddbimporter.dndbeyond.defintionKey") === infusedItem.definitionKey);
        if (!infusionFeature?.system.activities)
            continue;
        const infusionActivities = infusionFeature.system.activities
            .getByType("enchant");
        for (const activity of infusionActivities) {
            const activityEffects = activity.effects ?? [];
            const infusionEffectCount = activityEffects.length;
            const artificerLevel = rollData.classes?.artificer?.levels ?? 0;
            const infusionEffectIds = activityEffects.filter((e) => {
                if (infusionEffectCount === 1)
                    return true;
                // a null minimum matches the original >= null coercion (treated as 0)
                const minLevel = e.level?.min ?? 0;
                const maxLevel = e.level?.max ?? null;
                const appropriateLevel = artificerLevel >= minLevel
                    && (maxLevel === null || artificerLevel <= maxLevel);
                return appropriateLevel;
            }).map((e) => e._id);
            const infusionEffects = infusionFeature.getEmbeddedCollection("ActiveEffect")
                .filter((e) => e._id !== null && infusionEffectIds.includes(e._id));
            if (infusionEffects.length === 0)
                continue;
            for (const infusionEffect of infusionEffects) {
                await linkSelectedEnchantment(item, infusionEffect, activity, infusionFeature.name);
            }
        }
    }
}
