import DDBEnricherData from "../data/DDBEnricherData";
/**
 * Two activities: one to create the bubble, and one for the charm save made by
 * a creature that looks at it.
 */
export default class PolychromaticBubble extends DDBEnricherData {
    get type() {
        return DDBEnricherData.ACTIVITY_TYPES.UTILITY;
    }
    get activity() {
        return {
            name: "Create Bubble",
        };
    }
    get additionalActivities() {
        return [
            {
                init: {
                    name: "Save",
                    type: DDBEnricherData.ACTIVITY_TYPES.SAVE,
                },
                build: {
                    generateSave: true,
                    generateTarget: true,
                    generateRange: true,
                    generateActivation: true,
                    generateEffects: true,
                    noSpellslot: true,
                    saveOverride: {
                        ability: ["wis"],
                        dc: {
                            calculation: "spellcasting",
                            formula: "",
                        },
                    },
                    activationOverride: {
                        type: "special",
                        value: null,
                        condition: "A creature looks at the bubble",
                    },
                },
                overrides: {
                    noSpellslot: true,
                },
            },
        ];
    }
    get effects() {
        return [
            {
                name: "Polychromatic Bubble",
                activityMatch: "Create Bubble",
                options: {
                    durationSeconds: 60,
                },
            },
            {
                name: "Polychromatic Bubble: Charmed",
                activityMatch: "Save",
                options: {
                    expiry: "targetStart",
                },
                statuses: ["Charmed"],
            },
        ];
    }
}
