import DDBEnricherData from "../data/DDBEnricherData";
/**
 * Spilling the bag rolls nothing: it places a 10-foot square whose region fires the
 * "Ball Bearings Save" activity against each creature that enters, and that save knocks the
 * creature that fails it Prone.
 */
export default class BallBearings extends DDBEnricherData {
    get type() {
        return DDBEnricherData.ACTIVITY_TYPES.UTILITY;
    }
    get activity() {
        return {
            name: "Spill Ball Bearings",
            targetType: "creature",
            activationType: "action",
            addItemConsume: true,
            data: {
                target: {
                    override: true,
                    affects: {
                        type: "creature",
                    },
                    template: {
                        contiguous: false,
                        type: "square",
                        size: "10",
                        units: "ft",
                    },
                },
                range: {
                    override: true,
                    value: "10",
                    units: "ft",
                },
                behaviors: [
                    DDBEnricherData.BehaviorHelper.activity({
                        events: ["tokenEnter"],
                        activityName: "Ball Bearings Save",
                    }),
                ],
            },
        };
    }
    get additionalActivities() {
        return [
            {
                init: {
                    name: "Ball Bearings Save",
                    type: DDBEnricherData.ACTIVITY_TYPES.SAVE,
                },
                build: {
                    generateSave: true,
                    generateActivation: true,
                    generateConsumption: false,
                    generateTarget: true,
                    saveOverride: { ability: ["dex"], dc: { calculation: "", formula: "10" } },
                    activationOverride: {
                        type: "special",
                        condition: this.is2014
                            ? "Enters the area (not needed when moving through at half speed)"
                            : "Enters the area for the first time on a turn",
                    },
                    targetOverride: {
                        override: true,
                        affects: {
                            count: "1",
                            type: "creature",
                        },
                        template: {},
                    },
                    // the square is placed by "Spill Ball Bearings", so this rolls against whoever entered it
                    rangeOverride: {
                        override: true,
                        value: null,
                        units: "self",
                        special: "",
                    },
                },
            },
        ];
    }
    get effects() {
        return [
            {
                name: "Prone",
                activityMatch: "Ball Bearings Save",
                statuses: ["Prone"],
                options: {
                    transfer: false,
                },
            },
        ];
    }
}
