import { DICTIONARY, SETTINGS } from "../config/_module";
import logger from "./Logger";
import utils from "./Utils";
export default class DDBSources {
    static getSource(bookCode) {
        const source = (CONFIG.DDB?.sources ?? []).find((s) => typeof s?.name === "string" && s.name.toLowerCase() === bookCode.toLowerCase());
        return source ?? null;
    }
    /**
     * Given a book code e.g. DMG returns full name e.g. Dungeon Master's Guide. Returns empty string if not found.
     */
    static getBookName(bookCode) {
        const book = DDBSources.getSource(bookCode);
        if (book) {
            return book.description;
        }
        else {
            return "";
        }
    }
    /**
     * Given a book code e.g. DMG returns the book's DDB source ID. Returns null if not found.
     * @param bookCode
     * @returns
     */
    static getBookId(bookCode) {
        const src = DDBSources.getSource(bookCode);
        const id = src ? Number(src.id) : Number.NaN;
        return Number.isFinite(id) ? id : null;
    }
    static is2014Source(source) {
        const force2024 = DICTIONARY.source.is2024.includes(source.sourceId);
        if (force2024)
            return false;
        // if game is set to modern rules force items that have a 2024 source to be 2024
        if (utils.getSetting("rulesVersion", "dnd5e") === "modern") {
            if (force2024)
                return false;
        }
        const force2014 = DICTIONARY.source.is2014.includes(source.sourceId);
        if (force2014)
            return true;
        if (force2024)
            return false;
        return Number.isInteger(source.sourceId) && source.sourceId < 145;
    }
    static is2024Source(source) {
        const force2014 = DICTIONARY.source.is2014.includes(source.sourceId);
        if (force2014)
            return false;
        // if game is set to modern rules force items that have a 2024 source to be 2024
        if (utils.getSetting("rulesVersion", "dnd5e") === "modern") {
            if (force2014)
                return false;
        }
        const force2024 = DICTIONARY.source.is2024.includes(source.sourceId);
        if (force2024)
            return true;
        return Number.isInteger(source.sourceId) && source.sourceId >= 145;
    }
    static getAdjustedSourceBook(sourceBook) {
        const useBasicRules = utils.getSetting("use-basic-rules");
        if (!useBasicRules && ["free-rules", "br-2024", "BR-2024"].includes(sourceBook)) {
            return "PHB 2024";
        }
        else if (!useBasicRules && sourceBook === "BR") {
            return "SRD 5.1";
        }
        else {
            return sourceBook.replace("-", " ");
        }
    }
    static getDDBSourceBook(sourceBook) {
        if (["SRD 5.1"].includes(sourceBook)) {
            return "BR";
        }
        else {
            return sourceBook.replace(" ", "-");
        }
    }
    static tweakSourceData(source) {
        if (source.book === undefined)
            return;
        source.book = DDBSources.getAdjustedSourceBook(source.book);
        if (source.book === "BR") {
            source.license = "CC-BY-4.0";
        }
        else if (source.book === "br-2024") {
            source.book = "BR-2024";
        }
        if (utils.getSetting("no-source-book-pages"))
            source.page = "";
    }
    /**
     * Given a definition, returns an array of sourcebook objects.
     * The sourcebook object is an object with the following properties:
     * - book: the name of the sourcebook
     * - page: the page number of the sourcebook
     * - license: the license of the sourcebook
     * - custom: the custom name of the sourcebook
     * - id: the id of the sourcebook
     * If the definition has a sources array, it will return an array of sourcebook objects.
     * If the definition has a sourceId, it will return an array with one sourcebook object.
     * If the definition has a sourceIds array, it will return an array with one sourcebook object for each sourceId.
     * If the definition has no source information, it will return an empty array.
     * @param {TDDBSourceTypes} definition item definition
     * @returns {Array} an array of sourcebook objects
     */
    static getSourceData(definition) {
        const results = [];
        if ("sources" in definition && definition.sources && definition.sources.length > 0) {
            const definitionSources = definition.sources;
            const typeOneSources = definitionSources.filter((source) => source.sourceType === 1);
            const typeTwoSources = definitionSources.filter((source) => source.sourceType === 2);
            // is basic rules (e.g. SRD)
            const basicRules2014 = typeTwoSources.filter((source) => source.sourceId === 1);
            // should be type 2 but aren't for core weapons
            const basicRules2024 = definitionSources.filter((source) => source.sourceId === 148);
            const coreRules = definitionSources.filter((source) => source.sourceId === 198);
            const hasPage = definitionSources.some((source) => source.pageNumber !== null);
            const usePages = utils.getSetting("no-source-book-pages") === false;
            const useBasicRules = utils.getSetting("use-basic-rules");
            let sources = definitionSources;
            if (usePages && hasPage) {
                sources = definitionSources.filter((source) => source.pageNumber !== null);
            }
            // if just SRD on a source, lets add the PHB as well to avoid some _issues_
            if (sources.length === 1 && sources.find((s) => s.sourceType === 1 && s.sourceId === 1)) {
                sources.push({ sourceId: 2, sourceType: 1, pageNumber: null });
            }
            if (useBasicRules && coreRules.length > 0) {
                sources = coreRules;
            }
            else if (useBasicRules
                && utils.getSetting("rulesVersion", "dnd5e") === "modern" && basicRules2024.length > 0) {
                sources = basicRules2024;
            }
            else if (useBasicRules && basicRules2014.length > 0) {
                sources = basicRules2014;
            }
            else if (typeOneSources.length > 0) {
                sources = typeOneSources;
            }
            for (const ds of sources) {
                const ddbSource = CONFIG.DDB.sources.find((ddb) => ddb.id === ds.sourceId);
                const source = {
                    book: ddbSource ? ddbSource.name : "Homebrew",
                    page: String(ds.pageNumber ?? ""),
                    license: "",
                    custom: "",
                    id: ddbSource ? ddbSource.id : 9999999,
                    categoryId: ddbSource ? ddbSource.sourceCategoryId : 9999999,
                    rules: null,
                };
                DDBSources.tweakSourceData(source);
                results.push(source);
            }
        }
        else if ("sourceIds" in definition && definition.sourceIds) {
            for (const sourceId of definition.sourceIds) {
                const ddbSource = CONFIG.DDB.sources.find((ddb) => ddb.id === sourceId);
                const page = "sourcePageNumber" in definition && definition.sourcePageNumber ? String(definition.sourcePageNumber) : "";
                const source = {
                    book: ddbSource ? ddbSource.name : "Homebrew",
                    page,
                    license: "",
                    custom: "",
                    id: ddbSource ? ddbSource.id : 9999999,
                    categoryId: ddbSource ? ddbSource.sourceCategoryId : 9999999,
                    rules: null,
                };
                DDBSources.tweakSourceData(source);
                results.push(source);
            }
        }
        else if ("sourceId" in definition && definition.sourceId) {
            const ddbSource = CONFIG.DDB.sources.find((ddb) => ddb.id === definition.sourceId);
            const source = {
                book: ddbSource ? ddbSource.name : "Homebrew",
                page: definition.sourcePageNumber ?? "",
                license: "",
                custom: "",
                id: ddbSource ? ddbSource.id : 9999999,
                categoryId: ddbSource ? ddbSource.sourceCategoryId : 9999999,
                rules: null,
            };
            DDBSources.tweakSourceData(source);
            results.push(source);
        }
        else if ("isHomebrew" in definition && definition.isHomebrew) {
            const source = {
                book: "Homebrew",
                page: "",
                license: "",
                custom: "",
                id: 9999999,
                categoryId: 9999999,
                rules: null,
            };
            results.push(source);
        }
        return results;
    }
    /**
     * Parses the source data of a definition into a single source object
     * @param {TDDBSourceTypes} definition definition to parse
     * @returns {obj} a source object with the following properties: name, page, license, and custom
     */
    static parseSource(definition) {
        const sources = DDBSources.getSourceData(definition);
        const latestSource = sources.length > 0
            ? sources.reduce((prev, current) => {
                return (prev.id ?? 0) > (current.id ?? 0) ? prev : current;
            })
            : null;
        if (!latestSource)
            return {
                book: "Homebrew",
                page: "",
                license: "",
                custom: "",
                rules: null,
            };
        delete latestSource.id;
        return latestSource;
    }
    static addSourcesHook() {
        if (!utils.getSetting("register-source-books"))
            return;
        const ddbRaw = foundry.utils.getProperty(CONFIG, "DDB.sources");
        if (!ddbRaw)
            return;
        const sources = {};
        const validSources = ddbRaw.filter((s) => s.isReleased
            && (utils.getSetting("use-basic-rules")
                || !DICTIONARY.sourceCategories.basicRules.includes(s.id))).map((s) => {
            if (s.name === "br-2024")
                s.name = "BR-2024";
            return s;
        });
        for (const source of validSources) {
            sources[source.name.replace("-", " ")] = source.description;
        }
        sources["Homebrew"] = "Homebrew";
        Object.assign(CONFIG.DND5E.sourceBooks, sources);
        CONFIG.DDB.sources.push({
            "id": 9999999,
            "name": "Homebrew",
            "description": "Homebrew",
            "sourceCategoryId": 9999999,
            "isReleased": true,
            "avatarURL": "",
            "sourceURL": "my-collection",
        });
        CONFIG.DDB.sourceCategories.push({
            id: 9999999,
            name: "Homebrew",
            description: "Homebrew",
        });
    }
    /**
     * The RAW book selection from the deprecated per-book filter, whether or not the filter is
     * enabled and whether or not the books sit in an included category. Deliberately unfiltered:
     * the UI lists it so a stale selection can be seen and removed. Import paths must use
     * getBookFilter().effective instead.
     */
    static getSelectedSourceIds() {
        return utils.getSetting("munching-policy-muncher-sources")
            .map((id) => parseInt(`${id}`));
    }
    /**
     * The per-book filter as it applies to an import. The category filter runs first and strips
     * every source outside the included categories, so a selected book outside them can never
     * match; it is reported as ignored rather than applied. When NO selected book survives the
     * intersection the filter is treated as absent (effective = []), otherwise the whole import
     * would silently come back empty.
     */
    static getBookFilter() {
        const enabled = utils.getSetting("munching-policy-use-source-filter");
        const selected = DDBSources.getSelectedSourceIds();
        if (!enabled)
            return { enabled, selected, effective: [], ignored: [] };
        const allowed = new Set(DDBSources.getAllowedSourceIds());
        const effective = selected.filter((id) => allowed.has(id));
        const ignored = selected.filter((id) => !allowed.has(id));
        return { enabled, selected, effective, ignored };
    }
    static getExcludedCategoryIds() {
        const includedCategoryIds = DDBSources.getIncludedCategoryIds();
        return CONFIG.DDB.sourceCategories.map((category) => category.id)
            .filter((id) => !includedCategoryIds.includes(id));
    }
    static getIncludedCategoryIds() {
        return utils.getSetting("munching-policy-muncher-included-source-categories")
            .map((id) => parseInt(`${id}`));
    }
    static getSelectedMonsterTypeIds() {
        const chosenMonsterTypeIds = utils.getSetting("munching-policy-muncher-monster-types")
            .map((id) => parseInt(`${id}`));
        return chosenMonsterTypeIds;
    }
    static AlwaysExcludedCategoryIds = DICTIONARY.sourceCategories.excluded;
    static AlwaysHiddenCategoryIds = DICTIONARY.sourceCategories.hidden;
    static getAllExcludedCategoryIds() {
        return Array.from(new Set([
            ...DDBSources.AlwaysHiddenCategoryIds,
            ...DDBSources.AlwaysExcludedCategoryIds,
            ...DDBSources.getExcludedCategoryIds(),
        ]));
    }
    static getCategoriesWithBooks() {
        const sourceCategories = new Set(CONFIG.DDB.sources.map((s) => s.sourceCategoryId));
        return CONFIG.DDB.sourceCategories
            .filter((cat) => sourceCategories.has(cat.id));
    }
    static getAvailableCategories() {
        const cats = DDBSources.getCategoriesWithBooks()
            .filter((cat) => !DDBSources.AlwaysExcludedCategoryIds.includes(cat.id));
        return cats;
    }
    static getAvailableCategoryIds() {
        return DDBSources.getAvailableCategories()
            .map((source) => source.id);
    }
    static getDisplaySourceCategories(includeHomebrew = false) {
        return DDBSources.getAvailableCategories()
            .filter((c) => !DDBSources.AlwaysHiddenCategoryIds.includes(c.id)
            || (includeHomebrew && c.id === 9999999));
    }
    static getAllowedSources() {
        const excludedIds = DDBSources.getAllExcludedCategoryIds();
        const availableSources = CONFIG.DDB.sources
            .filter((source) => source.isReleased
            && !excludedIds.includes(source.sourceCategoryId));
        return availableSources;
    }
    static getAllowedSourceIds() {
        return DDBSources.getAllowedSources()
            .map((source) => source.id);
    }
    static getAllowedSourceCategoryIds() {
        const sourceSet = new Set(DDBSources.getAllowedSources()
            .map((source) => source.sourceCategoryId));
        return Array.from(sourceSet);
    }
    // sources to use in ui
    static getDisplaySources() {
        const excludedIds = [...DDBSources.AlwaysExcludedCategoryIds, ...DDBSources.AlwaysHiddenCategoryIds];
        const availableSources = CONFIG.DDB.sources
            .filter((source) => source.isReleased && !excludedIds.includes(source.sourceCategoryId));
        return availableSources;
    }
    static isSourceInAllowedCategory(source) {
        const sourceCategory = CONFIG.DDB.sources.find((s) => s.id == source.sourceId);
        if (!sourceCategory)
            return false;
        return !DDBSources.getAllExcludedCategoryIds().includes(sourceCategory.sourceCategoryId);
    }
    static async updateSelectedSources(ids) {
        await game.settings.set(SETTINGS.MODULE_ID, "munching-policy-muncher-sources", ids.map((id) => parseInt(`${id}`)));
    }
    static async updateIncludedCategories(ids) {
        await game.settings.set(SETTINGS.MODULE_ID, "munching-policy-muncher-included-source-categories", ids.map((id) => parseInt(`${id}`)));
    }
    static async updateSelectedMonsterTypes(ids) {
        await game.settings.set(SETTINGS.MODULE_ID, "munching-policy-muncher-monster-types", ids.map((id) => parseInt(`${id}`)));
    }
    static async updateAllowedWeaponPropertySources() {
        const allowedSourceIds = new Set(utils.getSetting("allowed-weapon-property-sources")
            .map((id) => parseInt(`${id}`)));
        const selectedAllowedSourceIds = utils.getSetting("munching-policy-muncher-sources")
            .map((id) => parseInt(`${id}`));
        selectedAllowedSourceIds.forEach((id) => allowedSourceIds.add(id));
        const sourcesNotExcluded = CONFIG.DDB.sources
            .filter((s) => !DDBSources.getAllExcludedCategoryIds().includes(s.sourceCategoryId));
        sourcesNotExcluded.forEach((s) => allowedSourceIds.add(s.id));
        await game.settings.set(SETTINGS.MODULE_ID, "allowed-weapon-property-sources", Array.from(allowedSourceIds));
    }
    static getDocumentSourceId(doc) {
        // items/spells path
        const dndbeyondSourceId = foundry.utils.getProperty(doc, "flags.ddbimporter.dndbeyond.sourceId");
        if (dndbeyondSourceId != null)
            return Number(dndbeyondSourceId);
        // monsters path
        const directSourceId = foundry.utils.getProperty(doc, "flags.ddbimporter.sourceId");
        if (directSourceId != null)
            return Number(directSourceId);
        // fallback: reverse-lookup system.source.book against CONFIG.DDB.sources
        const book = foundry.utils.getProperty(doc, "system.source.book");
        if (book) {
            const match = CONFIG.DDB.sources.find((s) => s.name === book || s.name === book.replace(" ", "-") || s.description === book);
            if (match)
                return match.id;
        }
        return null;
    }
    static getDocumentSourceCategoryId(doc) {
        // items/spells path
        const dndbeyondCatId = foundry.utils.getProperty(doc, "flags.ddbimporter.dndbeyond.sourceCategoryId");
        if (dndbeyondCatId != null)
            return Number(dndbeyondCatId);
        // monsters path
        const directCatId = foundry.utils.getProperty(doc, "flags.ddbimporter.sourceCategory");
        if (directCatId != null)
            return Number(directCatId);
        // derive from sourceId
        const sourceId = DDBSources.getDocumentSourceId(doc);
        if (sourceId != null) {
            const source = CONFIG.DDB.sources.find((s) => s.id === sourceId);
            if (source)
                return source.sourceCategoryId;
        }
        return null;
    }
    static getDocumentSourceIds(doc) {
        const ids = new Set();
        // spells store an array of sources
        const sources = foundry.utils.getProperty(doc, "flags.ddbimporter.sources");
        if (Array.isArray(sources)) {
            for (const s of sources)
                if (s?.sourceId != null)
                    ids.add(Number(s.sourceId));
        }
        // items/monsters store a single source id
        const single = DDBSources.getDocumentSourceId(doc);
        if (single != null)
            ids.add(single);
        return [...ids];
    }
    static matchesSourceFilter(doc, { sourceIds, categoryIds }) {
        if (sourceIds?.length) {
            const docSourceId = DDBSources.getDocumentSourceId(doc);
            if (docSourceId != null && sourceIds.includes(docSourceId))
                return true;
        }
        if (categoryIds?.length) {
            const docCatId = DDBSources.getDocumentSourceCategoryId(doc);
            if (docCatId != null && categoryIds.includes(docCatId))
                return true;
        }
        return false;
    }
    static getDocumentSourceBookName(doc) {
        const sourceId = DDBSources.getDocumentSourceId(doc);
        if (sourceId != null) {
            const source = CONFIG.DDB.sources.find((s) => s.id === sourceId);
            if (source)
                return source.description || source.name;
        }
        const book = foundry.utils.getProperty(doc, "system.source.book");
        return book || "Unknown";
    }
    /**
     * The cover image for a source book, or null when DDB does not have one.
     *
     * A book with no cover comes back with the avatar directory and no file on the end
     * (`https://www.dndbeyond.com/avatars/`, currently about a fifth of the catalog) rather than an
     * empty string, so a plain truthiness check passes and the page renders a broken image.
     * @param {{ avatarURL?: string | null } | null} [source]  A DDB source book.
     */
    static getSourceCoverURL(source) {
        const url = source?.avatarURL?.trim();
        if (!url)
            return null;
        const path = url.split(/[?#]/)[0];
        const file = path.slice(path.lastIndexOf("/") + 1);
        return file === "" ? null : url;
    }
    static getBooksInCategories(categoryIds) {
        const books = CONFIG.DDB.sources.filter((book) => categoryIds.includes(book.sourceCategoryId));
        return books;
    }
    static getBookIdsInCategories(categories) {
        const books = DDBSources.getBooksInCategories(categories);
        return books.map((book) => book.id);
    }
    // Basic Rules (1), PHB (2), br-2024 (148), PHB-2024 (145). Always in play,
    // as content in these books underpins everything else.
    static CoreSourceIds = [1, 2, 148, 145];
    /**
     * The flat set of source ids the user has chosen, across all chosen categories,
     * seeded with the core books.
     */
    static getChosenSourceIdSet({ includeCore = true, useOverride = true } = {}) {
        const sourceIds = new Set(includeCore ? DDBSources.CoreSourceIds : []);
        for (const category of DDBSources.getChosenCategoriesAndBooks(useOverride)) {
            for (const sourceId of category.sourceIds) {
                sourceIds.add(sourceId);
            }
        }
        return sourceIds;
    }
    /**
     * Does a raw DDB definition (class, subclass, class feature, trait...) come from
     * one of the given source ids? Definitions without source data are allowed through
     * by default, as we can't judge them.
     */
    static isDefinitionInSourceIds(definition, allowedSourceIds, { allowMissingSources = true } = {}) {
        if (!definition.sources?.length)
            return allowMissingSources;
        const allowed = allowedSourceIds instanceof Set
            ? allowedSourceIds
            : new Set(allowedSourceIds);
        return definition.sources.some((source) => allowed.has(source.sourceId));
    }
    /** Bucket used by groupBySourceIds for definitions DDB gives no source. */
    static UNKNOWN_SOURCE_ID = 0;
    /**
     * The book a definition is primarily attributed to. DDB lists extra sources
     * for reprints and setting references; sourceType 1 is the actual book, so
     * prefer it and only fall back to the first entry when nothing is typed.
     */
    static getPrimarySource(definition) {
        const sources = definition?.sources ?? [];
        return sources.find((source) => source.sourceType === 1) ?? sources[0] ?? null;
    }
    /** The DDB source category owning a source id, or null when it is unknown. */
    static getSourceCategoryForSourceId(sourceId) {
        const source = (CONFIG.DDB?.sources ?? []).find((s) => s.id == sourceId);
        if (!source)
            return null;
        return (CONFIG.DDB?.sourceCategories ?? []).find((c) => c.id === source.sourceCategoryId) ?? null;
    }
    /**
     * Break a single proxy payload down into one bucket per DDB source book,
     * filing each entry once for every source it lists.
     *
     * DDB can list several sources for one definition (a spell reprinted in a
     * later compendium keeps both, and most core content lists the SRD entry
     * first). The muncher's own source filter matches on any of them, so the
     * buckets deliberately overlap - a source's bucket is "everything a per-book
     * import of this book would pull", not "what DDB primarily attributes to it".
     * Bucketing on one source instead would leave books that only ever appear as
     * a secondary entry with no bucket at all.
     *
     * Entries with no source data go to UNKNOWN_SOURCE_ID
     */
    static groupBySourceIds(entries, getDefinition) {
        const grouped = new Map();
        for (const entry of entries) {
            // one definition can repeat a source id with different sourceTypes
            const sourceIds = new Set((getDefinition(entry)?.sources ?? []).map((source) => source.sourceId));
            if (sourceIds.size === 0)
                sourceIds.add(DDBSources.UNKNOWN_SOURCE_ID);
            for (const sourceId of sourceIds) {
                const bucket = grouped.get(sourceId);
                if (bucket)
                    bucket.push(entry);
                else
                    grouped.set(sourceId, [entry]);
            }
        }
        return grouped;
    }
    static getChosenCategoriesAndBooks(useOverride = true) {
        const sourceIdArrays = [];
        const sourceCategoryIds = DDBSources.getAllowedSourceCategoryIds();
        const overrideSources = useOverride ? DDBSources.getBookFilter().effective : [];
        for (const sourceCategoryId of sourceCategoryIds) {
            const sourceIds = DDBSources.getBookIdsInCategories([sourceCategoryId]);
            const filteredSourceIds = sourceIds.filter((id) => overrideSources.length === 0 || overrideSources.includes(id));
            if (filteredSourceIds.length === 0)
                continue;
            sourceIdArrays.push({
                categoryId: sourceCategoryId,
                sourceIds: filteredSourceIds,
            });
        }
        logger.debug(`DDBSources.getChosenCategoriesAndBooks`, {
            useOverride,
            sourceCategoryIds,
            overrideSources,
            sourceIdArrays,
        });
        return sourceIdArrays;
    }
}
