import DDBEnricherData from "../../data/DDBEnricherData";
export default class SuperiorDefense extends DDBEnricherData {
    get type() {
        return DDBEnricherData.ACTIVITY_TYPES.UTILITY;
    }
    get activity() {
        return {
            name: "Superior Defense",
            activationType: "special",
            activationCondition: "At the start of your turn",
            targetType: "self",
            addItemConsume: true,
            itemConsumeTargetName: this.ddbEnricher.isParentClass2014 ? "Ki" : "Monk's Focus",
            itemConsumeValue: 3,
            data: {
                duration: {
                    value: "1",
                    units: "minute",
                },
            },
        };
    }
    get effects() {
        return [
            {
                name: "Superior Defense",
                options: {
                    durationSeconds: 60,
                    description: "Resistance to all damage except Force. Ends early if you have the Incapacitated condition.",
                },
                changes: DDBEnricherData.allDamageTypes(["force"]).map((element) => DDBEnricherData.ChangeHelper.damageResistanceChange(element)),
            },
        ];
    }
    get clearAutoEffects() {
        return true;
    }
}
