import DDBEnricherData from "../../data/DDBEnricherData";
import { emanation, regionTrigger } from "../../data/RegionBuilders";
export default class CrownOfHorns extends DDBEnricherData {
    // DDB lists the Horned King form under both "Crown of Horns" and its
    // "Dark Heart" benefit with identical text; only the primary name builds
    // anything so a character carrying both entries gets one set of activities
    get isPrimary() {
        return this.name === "Crown of Horns";
    }
    get type() {
        if (!this.isPrimary)
            return DDBEnricherData.ACTIVITY_TYPES.NONE;
        return DDBEnricherData.ACTIVITY_TYPES.UTILITY;
    }
    get activity() {
        if (!this.isPrimary)
            return null;
        return {
            name: "Manifest Crown of Horns",
            targetType: "self",
            activationType: "bonus",
            addItemConsume: true,
            data: {
                target: emanation("20", "self"),
                behaviors: [
                    DDBEnricherData.BehaviorHelper.activity({
                        ownerTurn: true,
                        fireOnPlacement: true,
                        events: ["tokenTurnStart"],
                        activityName: "King of All: Enticement",
                        activityChoices: ["Enticement", "Wickedness", "Terror"].map((choice) => `King of All: ${choice}`),
                    }),
                ],
                duration: {
                    value: "1",
                    units: "minute",
                },
            },
        };
    }
    get additionalActivities() {
        if (!this.isPrimary)
            return [];
        return [
            ...["Enticement", "Wickedness", "Terror"].map((choice) => {
                const trigger = regionTrigger(`King of All: ${choice}`, {
                    condition: "On activation, and at the start of each of your turns, choose a creature you can see in the 20 foot aura",
                    save: { ability: ["cha"], calculation: "spellcasting" },
                });
                return {
                    ...trigger,
                    build: {
                        ...trigger.build,
                        targetOverride: {
                            override: true,
                            affects: { type: "creature", count: "1", choice: true },
                            template: {},
                        },
                    },
                };
            }),
            {
                init: {
                    name: "Spend Pact Slot to Restore Use",
                    type: DDBEnricherData.ACTIVITY_TYPES.UTILITY,
                },
                build: {
                    generateConsumption: true,
                    generateTarget: true,
                    generateActivation: true,
                    generateUtility: true,
                    activationOverride: {
                        type: "none",
                        value: null,
                        condition: "",
                    },
                    consumptionOverride: {
                        targets: [
                            {
                                type: "itemUses",
                                target: "",
                                value: -1,
                                scaling: { mode: "", formula: "" },
                            },
                            {
                                type: "attribute",
                                value: "1",
                                target: "spells.pact.value",
                            },
                        ],
                    },
                },
            },
        ];
    }
    get clearAutoEffects() {
        return this.isPrimary;
    }
    get override() {
        if (!this.isPrimary)
            return null;
        return {
            uses: {
                spent: 0,
                recovery: [
                    {
                        period: "lr",
                        type: "recoverAll",
                    },
                ],
                max: "1",
            },
            descriptionSuffix: `
<section class="secret ddbSecret" id="secret-ddbCrownOfHorns">
<p><strong>Implementation Details</strong></p>
<p>Choose a creature and one King of All save. Each save applies only its named effect.</p>
</section>`,
        };
    }
    get effects() {
        if (!this.isPrimary)
            return [];
        return [
            {
                name: "Crown of Horns: Dark Heart",
                activityMatch: "Manifest Crown of Horns",
                options: {
                    durationSeconds: 60,
                    description: "Once on each of your turns when you damage a creature, it takes an extra 1d8 Necrotic damage.",
                },
                ac5eChanges: [
                    DDBEnricherData.ChangeHelper.ac5eChange("bonus=1d8[necrotic]; oncePerTurn", 20, "flags.automated-conditions-5e.damage.bonus"),
                ],
            },
            {
                name: "King of All: Enticement",
                activityMatch: "King of All: Enticement",
                statuses: ["Charmed"],
                options: {
                    expiry: "sourceStart",
                    description: "Charmed until the start of the origin's next turn.",
                },
            },
            {
                name: "King of All: Wickedness",
                activityMatch: "King of All: Wickedness",
                options: {
                    expiry: "sourceStart",
                    description: "Disadvantage on attack rolls and ability checks until the start of the origin's next turn.",
                },
                changes: [
                    DDBEnricherData.ChangeHelper.ruleDisadvantageChange("attack"),
                    DDBEnricherData.ChangeHelper.ruleDisadvantageChange("check"),
                ],
            },
            {
                name: "King of All: Terror",
                activityMatch: "King of All: Terror",
                statuses: ["Frightened"],
                options: {
                    expiry: "sourceStart",
                    description: "Frightened until the start of the origin's next turn; it must move away from the origin by the safest route on its turn.",
                },
            },
        ];
    }
}
