import DDBStickerBrowser from "../../apps/DDBStickerBrowser";
import { logger } from "../../lib/_module";
export function addStickerBrowserControl(controls) {
    // Fast, synchronous gate
    if (!DDBStickerBrowser.hasAccess())
        return;
    if (!controls.tiles?.tools)
        return;
    controls.tiles.tools["ddb-stickers"] = {
        name: "ddb-stickers",
        order: 99,
        title: "DDB Sticker Browser",
        icon: "fa-solid fa-shapes",
        button: true,
        visible: true,
        onChange: (_event, active) => {
            if (active === false)
                return;
            DDBStickerBrowser.open().catch((error) => {
                logger.error("Unable to open the DDB Sticker Browser", { error });
            });
        },
    };
}
