import DDBEnricherData from "../data/DDBEnricherData";
export default class WrathOfNature extends DDBEnricherData {
    get activity() {
        return {
            data: {
                behaviors: [
                    DDBEnricherData.BehaviorHelper.difficultTerrain({ types: ["plants"] }),
                ],
            },
        };
    }
    get override() {
        return {
            data: {
                system: {
                    target: {
                        affects: {
                            type: "enemy",
                        },
                    },
                },
            },
        };
    }
}
