import _MonsterFeatureSupport from "./_MonsterFeatureSupport";
/** Riders match the parser's numbered modes; successful-save riders remain independently applicable. */
export default class CataclysmicEvent extends _MonsterFeatureSupport {
    get modes() {
        return ["1: Clinging Flames", "2: Freezing Waves", "3: Raging Storm", "4: Swallowing Earth"].every((name) => this.text.includes(name));
    }
    get clearAutoEffects() {
        return this.modes;
    }
    get effects() {
        if (!this.modes)
            return [];
        return [
            { name: "Clinging Flames", statuses: ["Burning"], activityMatch: "1: Clinging Flames", onSave: true },
            { name: "Waves: Prone", statuses: ["Prone"], activityMatch: "2: Freezing Waves" },
            {
                name: "Waves: Speed Zero",
                changes: [_MonsterFeatureSupport.ChangeHelper.movementMultiplierChange("0", 20)],
                activityMatch: "2: Freezing Waves",
                onSave: true,
                options: { expiry: "targetEnd" },
            },
            {
                name: "Inside Storm Cloud",
                statuses: ["Blinded", "Deafened"],
                activityMatch: "3: Raging Storm",
                onSave: true,
                options: {
                    expiry: null,
                    durationSeconds: null,
                    description: "Apply only while entirely inside the cloud; verbal spell components are unavailable. Remove on leaving, after 1 minute, or when the source uses Cataclysmic Event again.",
                },
            },
            {
                name: "Buried",
                statuses: ["Prone", "Restrained", "coverTotal", "suffocation"],
                activityMatch: "4: Swallowing Earth",
                options: {
                    expiry: null,
                    durationSeconds: null,
                    description: "A successful escape check ends burial, restraint, total cover, and suffocation. Resolve standing from Prone separately.",
                },
            },
        ];
    }
    async cleanup() {
        if (!this.modes)
            return;
        const check = this.check();
        if (!check)
            return;
        // Building this after the parser's modes preserves its automatic multi-save generation.
        const activity = this.parser._getCheckActivity({ name: "Buried: Escape Check" }, {
            generateCheck: true,
            checkOverride: check,
            generateConsumption: false,
            generateDamage: false,
            includeBaseDamage: false,
            activationOverride: {
                type: "action",
                value: 1,
                condition: "The buried creature or another creature within 5 feet can attempt this check.",
            },
            targetOverride: { affects: { type: "creature", count: "1" }, template: { type: "" } },
            rangeOverride: { units: "any" },
        });
        activity.data._id = "ddbBuriedCheck01";
        activity.data.effects = [];
        this.document.system.activities[activity.data._id] = activity.data;
    }
}
