import DDBEnricherData from "../../data/DDBEnricherData";
/**
 * The transformation toggle itself. DDB's matching action ships no limitedUse, so the once per
 * short rest limit is added here; the Hybrid Transformation Features enchantment consumes it via
 * CONSUMPTION_LINKS.
 *
 * Hybrid Transformation Mastery (18th level) removes the limit; that is not modelled here because
 * clearing max would break the consumption target on the child feature.
 *
 * Combines Stalkers Prowess changes as well
 */
export default class HybridTransformation extends DDBEnricherData {
    // One activity pair per (die, attack bonus)
    static STRIKE_IDS = {
        small: { action: "ddbLycanStrike01", bonus: "ddbLycanStrike02" },
        smallImproved: { action: "ddbLycanStrike21", bonus: "ddbLycanStrike22" },
        large: { action: "ddbLycanStrike11", bonus: "ddbLycanStrike12" },
        largeGreater: { action: "ddbLycanStrike31", bonus: "ddbLycanStrike32" },
    };
    static BLOODLUST_ID = "ddbLycanBloodlst";
    // Predatory Strikes lets you use either Strength or Dexterity, so the ability mod is suppressed
    // and both the mod and proficiency are rolled into the attack bonus instead.
    static ATTACK_BONUS = "max(@abilities.str.mod, @abilities.dex.mod) + @prof";
    static DAMAGE_BONUS = "max(@abilities.str.mod, @abilities.dex.mod)";
    get type() {
        return DDBEnricherData.ACTIVITY_TYPES.ENCHANT;
    }
    get activity() {
        return {
            name: "Hybrid Transformation",
            targetType: "self",
            rangeSelf: true,
            activationType: "bonus",
            noTemplate: true,
            addItemConsume: true,
            data: {
                enchant: {
                    self: true,
                },
                visibility: {
                    identifier: "blood-hunter",
                },
                duration: {
                    value: "1",
                    units: "hour",
                },
            },
        };
    }
    /**
     * The strike pair for one level band. `attackBonus` is Stalker's Prowess' Improved Predatory
     * Strikes, which only applies in hybrid form and so is carried here rather than as a rule on
     * that feature.
     */
    _strikeActivities(denomination, ids, attackBonus = 0) {
        const damageParts = [
            DDBEnricherData.basicDamagePart({
                customFormula: `1d${denomination} + ${HybridTransformation.DAMAGE_BONUS}`,
                types: ["bludgeoning", "slashing"],
            }),
        ];
        const attack = {
            ability: "none",
            bonus: attackBonus > 0
                ? `${HybridTransformation.ATTACK_BONUS} + ${attackBonus}`
                : HybridTransformation.ATTACK_BONUS,
            type: {
                value: "melee",
                classification: "unarmed",
            },
        };
        const target = {
            affects: {
                count: "1",
                type: "creature",
            },
        };
        return [
            {
                init: {
                    name: "Predatory Strike",
                    type: DDBEnricherData.ACTIVITY_TYPES.ATTACK,
                },
                build: {
                    generateAttack: true,
                    generateDamage: true,
                    generateRange: true,
                    generateTarget: true,
                    generateActivation: true,
                    generateConsumption: false,
                    damageParts,
                    activationOverride: {
                        type: "action",
                    },
                },
                overrides: {
                    noConsumeTargets: true,
                    id: ids.action,
                    data: {
                        attack,
                        target,
                        range: { value: 5, units: "ft" },
                        duration: { units: "inst" },
                    },
                },
            },
            {
                init: {
                    name: "Predatory Strike (Bonus Action)",
                    type: DDBEnricherData.ACTIVITY_TYPES.ATTACK,
                },
                build: {
                    generateAttack: true,
                    generateDamage: true,
                    generateRange: true,
                    generateTarget: true,
                    generateActivation: true,
                    generateConsumption: false,
                    damageParts,
                    activationOverride: {
                        type: "bonus",
                        condition: "After you take the Attack action to make an unarmed strike",
                    },
                },
                overrides: {
                    id: ids.bonus,
                    noConsumeTargets: true,
                    data: {
                        attack,
                        target,
                        range: { value: 5, units: "ft" },
                        duration: { units: "inst" },
                    },
                },
            },
        ];
    }
    // Feral Might's damage bands (3rd/11th/18th) and the Improved Predatory Strikes attack bands
    // (7th/11th/18th) differ only below 7th level.
    static BANDS = [
        {
            damageBonus: 1, attackBonus: 0, denomination: 6, effectId: "ddbLycanForm0001",
            strikeIds: HybridTransformation.STRIKE_IDS.small, level: { min: null, max: 6 },
        },
        {
            damageBonus: 1, attackBonus: 1, denomination: 6, effectId: "ddbLycanForm0001",
            strikeIds: HybridTransformation.STRIKE_IDS.smallImproved, level: { min: 7, max: 10 },
        },
        {
            damageBonus: 2, attackBonus: 2, denomination: 8, effectId: "ddbLycanForm0002",
            strikeIds: HybridTransformation.STRIKE_IDS.large, level: { min: 11, max: 17 },
        },
        {
            damageBonus: 3, attackBonus: 3, denomination: 8, effectId: "ddbLycanForm0003",
            strikeIds: HybridTransformation.STRIKE_IDS.largeGreater, level: { min: 18, max: null },
        },
    ];
    get additionalActivities() {
        return [
            ...HybridTransformation.BANDS.flatMap((band) => this._strikeActivities(band.denomination, band.strikeIds, band.attackBonus)),
            {
                init: {
                    name: "Bloodlust",
                    type: DDBEnricherData.ACTIVITY_TYPES.SAVE,
                },
                build: {
                    generateSave: true,
                    generateRange: false,
                    generateTarget: true,
                    generateActivation: true,
                    generateConsumption: false,
                    saveOverride: {
                        ability: ["wis"],
                        dc: { calculation: "", formula: "8" },
                    },
                    activationOverride: {
                        type: "turnStart",
                        condition: "You start your turn with fewer hit points than half your hit point maximum",
                    },
                },
                overrides: {
                    id: HybridTransformation.BLOODLUST_ID,
                    useActivitySnippet: true,
                    targetType: "self",
                    noConsumeTargets: true,
                    data: {
                        range: { units: "self" },
                        duration: { units: "inst" },
                    },
                },
            },
        ];
    }
    _hybridFormEffect(damageBonus, id) {
        return {
            name: `Hybrid Form (+${damageBonus})`,
            statuses: ["Transformed"],
            // rider effects are pulled in by the enchantment, they must never attach to an activity
            activitiesMatch: ["Not real"],
            options: {
                transfer: true,
                durationSeconds: 3600,
                description: "Resilient Hide's AC bonus only applies while you are not wearing heavy armor.",
            },
            changes: [
                // Feral Might
                DDBEnricherData.ChangeHelper.unsignedAddChange(`+${damageBonus}`, 20, "system.rolls.damage.mwak.bonus"),
                DDBEnricherData.ChangeHelper.advantageAbilityCheckChange("str"),
                DDBEnricherData.ChangeHelper.advantageAbilitySaveChange("str"),
                // Resilient Hide
                DDBEnricherData.ChangeHelper.damageResistanceChange("bludgeoning"),
                DDBEnricherData.ChangeHelper.damageResistanceChange("piercing"),
                DDBEnricherData.ChangeHelper.damageResistanceChange("slashing"),
                DDBEnricherData.ChangeHelper.unsignedAddChange("mgc", 20, "system.traits.dr.bypasses"),
                DDBEnricherData.ChangeHelper.unsignedAddChange("sil", 20, "system.traits.dr.bypasses"),
                DDBEnricherData.ChangeHelper.unsignedAddChange("1", 20, "system.attributes.ac.bonus"),
            ],
            data: {
                _id: id,
            },
        };
    }
    _enchantProfile({ effectId, strikeIds, level }) {
        return {
            name: "Hybrid Form",
            statuses: ["Transformed"],
            type: "enchant",
            activityMatch: "Hybrid Transformation",
            options: {
                durationSeconds: 3600,
            },
            changes: [
                DDBEnricherData.ChangeHelper.overrideChange("{} (Hybrid Form)", 10, "name"),
            ],
            data: {
                flags: {
                    ddbimporter: {
                        effectIdLevel: level,
                        activityRiders: [strikeIds.action, strikeIds.bonus, HybridTransformation.BLOODLUST_ID],
                        effectRiders: [effectId],
                    },
                },
            },
        };
    }
    get effects() {
        const riders = new Map();
        for (const band of HybridTransformation.BANDS) {
            if (riders.has(band.effectId))
                continue;
            riders.set(band.effectId, this._hybridFormEffect(band.damageBonus, band.effectId));
        }
        return [
            ...riders.values(),
            ...HybridTransformation.BANDS.map((band) => this._enchantProfile(band)),
        ];
    }
    /**
     * "Hybrid Transformation Features" is skipped as its own document, so its text (Feral Might,
     * Resilient Hide, Predatory Strikes, Bloodlust) is folded in here alongside the automation.
     */
    get _featuresDescription() {
        const description = this.getClassFeatureDescription({
            featureName: "Hybrid Transformation Features",
            subClassName: "Order of the Lycan",
        });
        return description ? `<h3>Hybrid Transformation Features</h3>${description}` : "";
    }
    // matches a single non-nested blockquote; a DOM round trip is not used here because
    // re-serialising would escape the & in Foundry's &Reference[...] enrichers
    static BLOCKQUOTE_REGEX = /<blockquote\b[^>]*>(?:(?!<\/blockquote>)[\s\S])*<\/blockquote>\s*/gi;
    _stripBuilderNote(html) {
        return DDBEnricherData.stripBuilderNote(html, "Character Builder");
    }
    get override() {
        return {
            data: {
                name: "Hybrid Transformation",
            },
            uses: this._getUsesWithSpent({
                type: "class",
                // DDB names the action with a trailing space
                name: "Hybrid Transformation",
                includesName: true,
                max: "1",
                period: "sr",
            }),
            // only the transformation toggle spends a Hybrid Transformation use
            ignoredConsumptionActivities: ["Predatory Strike", "Predatory Strike (Bonus Action)", "Bloodlust"],
            descriptionSuffix: `${this._featuresDescription}<p><em>The Predatory Strike activities are banded by level and include the Improved Predatory Strikes attack bonus from Stalker's Prowess. Crimson Rite is not applied to them automatically; add the rite die to the damage roll manually or apply the enchantment to this item.</em></p>`,
            // runs after descriptionSuffix has been appended
            func: ({ enricher }) => {
                const description = enricher.data.system.description;
                if (!description)
                    return;
                description.value = this._stripBuilderNote(description.value);
                if (description.chat)
                    description.chat = this._stripBuilderNote(description.chat);
            },
        };
    }
}
