import DDBEnricherData from "../data/DDBEnricherData";
export default class FleshToStone extends DDBEnricherData {
    get type() {
        return DDBEnricherData.ACTIVITY_TYPES.SAVE;
    }
    get activity() {
        return {
            name: "Cast",
        };
    }
    get additionalActivities() {
        return [
            {
                duplicate: true,
                overrides: {
                    name: "Save (no spellslot)",
                    activationType: "special",
                    removeSpellSlotConsume: true,
                    noConsumeTargets: true,
                },
            },
        ];
    }
    get clearAutoEffects() {
        return this.useMidiAutomations;
    }
    get effects() {
        const effects = [];
        if (!this.is2014) {
            effects.push({
                name: "Unable to Move",
                activityMatch: "Cast",
                onSave: true,
                changes: [
                    DDBEnricherData.ChangeHelper.movementMultiplierChange("0", 20),
                ],
                options: { expiry: "sourceStart" },
            });
        }
        effects.push({
            name: "Flesh to Stone (Automation)",
            activityMatch: "Cast",
            midiOnly: true,
            statuses: ["Restrained"],
            macroChanges: [
                { macroType: "spell", macroName: "fleshToStone.js" },
            ],
            options: {
                durationSeconds: 60,
                expiry: "turnStart",
            },
            data: {
                flags: {
                    dae: {
                        macroRepeat: "endEveryTurn",
                    },
                },
            },
        });
        return effects;
    }
    get itemMacro() {
        return {
            type: "spell",
            name: "fleshToStone.js",
        };
    }
}
